            if (initiatedMillis <= cutoffMillis) {
                events.add(new Event(1, initiatedMillis, transfer.id(), Kind.TRANSFER_INITIATE,
                        null, transfer));
                Long decidedMillis = transfer.decidedAt() == null ? null : toWallMillis(transfer.decidedAt());
                if (decidedMillis != null && decidedMillis <= cutoffMillis) {
