                    }
                    latestInspectionPassed = passed;
                    status = passed ? EvidenceStatus.SEALED : EvidenceStatus.SEAL_BROKEN;
                    activeLoan = null;
                    views.add(new FrozenChainEventView(seq, "LOAN_RETURN", loan.returnedAt(),
