            seq++;
            switch (event.kind) {
                case INTAKE -> {
                    custodian = initialCustodian;
                    status = EvidenceStatus.SEALED;
                    views.add(new FrozenChainEventView(seq, "INTAKE", evidence.createdAt(),
                            initialCustodian, null, null, null, null, null, null, null, null, null));
                }
