                    LoanRecord loan = event.loan;
                    activeLoan = loan;
                    status = EvidenceStatus.BORROWED;
                    views.add(new FrozenChainEventView(seq, "LOAN_BORROW", loan.loanAt(),
                            loan.custodianId(), null, null, null, null, loan.borrowerId(),
