                .containsExactly(1, 2, 3);
        // 两个修订包均基于 v1，彼此独立冻结
        assertThat(packages.get(0).basePackageKey()).isEqualTo(baseKey);
        assertThat(packages.get(1).basePackageKey()).isEqualTo(baseKey);
    }
}

