/**
 * 推断入库时保管人（链锚点）：
 * 从未发生已接受交接时，当前保管人从未被交接改变，即入库保管人；
 * 存在已接受交接时，取最早一条交接记录的发起人（首条交接的起点即入库保管人）。
 */
private String resolveInitialCustodian(Evidence evidence) {
    List<TransferRecord> transfers = transferRepository.findByEvidenceKey(evidence.evidenceKey());
    boolean anyAccepted = transfers.stream()
            .anyMatch(t -> t.status() == TransferStatus.ACCEPTED);
    if (anyAccepted) {
        return transfers.get(0).fromCustodian();
    }
    return evidence.custodianId();
}

